    "industrial.clinicalNote": "<strong>Klinischer Hinweis:</strong> Ein Industrial-Piercing verbindet zwei unabhängige Knorpelkanäle über eine einzelne starre Stange. Beidseitige Schwellungen in den ersten 6–12 Monaten erfordern eine ausreichende Erstlänge, um Ischämie, Migration und bleibende Knorpelverformungen zu vermeiden. Vor dem Downsizing stets einen qualifizierten Piercer nach etablierter Berufspraxis konsultieren.",
